#!/usr/bin/env python3
"""Preview actual packaged-client exports from a passing visual fixture."""
from pathlib import Path
import argparse,hashlib,json,shutil,subprocess
ROOT=Path(__file__).resolve().parents[1]
ap=argparse.ArgumentParser();ap.add_argument('--frames',type=Path);args=ap.parse_args()
if args.frames:
 base=args.frames.resolve()
else:
 candidates=sorted((ROOT/'output/tests/divine-bolt-visuals').glob('*/receipt.json'),key=lambda p:p.stat().st_mtime)
 if not candidates:raise SystemExit('Run tests/myworld/test-divine-bolt-visuals.py first.')
 base=candidates[-1].parent
receipt=json.loads((base/'receipt.json').read_text())
assert receipt['passed'] and receipt['clientSha256']==hashlib.sha256((ROOT/'Client_Base/Open_RSC_Client.jar').read_bytes()).hexdigest(),'Re-run visual fixture for current client.'
out=Path(subprocess.check_output(['python3',str(ROOT/'scripts/workspace-layout.py'),'path','art','god-crossbow-prayer-shots','--mkdir'],text=True,cwd=ROOT).strip())/'study-v4';out.mkdir(exist_ok=True)
for p in (base/'true').glob('*.png'):shutil.copyfile(p,out/p.name)
shutil.copyfile(ROOT/'dev/myworld/assets/runtime/ui/prayer/ranged-power1.png',out/'existing-prayer.png')
(out/'index.html').write_text('''<!doctype html><meta charset="utf-8"><title>Holy bolts — prayer icons and flight visuals</title>
<style>body{font:16px system-ui;background:#1d252e;color:#eee;margin:24px}h1{font-size:25px}h2{font-size:19px}main,.icons,.effects{display:flex;flex-wrap:wrap;gap:16px}.card{padding:16px;background:#29343f;border:1px solid #4a5967;border-radius:8px}canvas{display:block;background:#202830}img,canvas{image-rendering:pixelated}small{color:#bbc5cd}button,select{font:inherit;background:#344655;color:white;padding:6px;border:1px solid #6a8395}p{max-width:1050px}.icons img{margin:10px;vertical-align:middle}.tag{color:#d9e49c}</style>
<h1>Holy bolts: visual review</h1><p class="tag">Candidate artwork — not installed in your private client yet.</p><p>White prayer pictograms, directional flight for basic and holy bolts, larger enveloping trails, 4× Revelation, doubled bleed, and corrected poison size. These images were exported through the actual packaged-client loaders.</p>
<h2>Prayer icons</h2><div class="icons"><section class="card"><h2>Saradomin: Divine Bolts</h2><img src="divine-bolts.png" width="32" height="32"><img src="divine-bolts.png" width="128" height="128"><p>Bolt piercing a heart</p></section><section class="card"><h2>Guthix: Thorned Bolts</h2><img src="thorned-bolts.png" width="32" height="32"><img src="thorned-bolts.png" width="128" height="128"><p>Bolt wrapped in brambles</p></section><section class="card"><h2>Zamorak: Bolts of Wrath</h2><img src="bolts-of-wrath.png" width="32" height="32"><img src="bolts-of-wrath.png" width="128" height="128"><p>Bolt dripping blood</p></section><section class="card"><h2>Existing style reference</h2><img src="existing-prayer.png" width="32" height="32"><img src="existing-prayer.png" width="128" height="128"></section></div>
<h2>Flight</h2><p><button id="pause">Pause</button> <select id="direction"><option value="auto">Cycle all eight directions</option><option value="0">Right</option><option value="1">Down/right</option><option value="2">Down</option><option value="3">Down/left</option><option value="4">Left</option><option value="5">Up/left</option><option value="6">Up</option><option value="7">Up/right</option></select> <label><input id="large" type="checkbox"> 2× pixel inspection</label></p><main></main>
<h2>On-character effects</h2><p>Zoom comparison: <select id="effectZoom"><option value="0.5">Zoomed out — 50%</option><option value="1" selected>Reference — 100%</option><option value="1.5">Zoomed in — 150%</option><option value="2">Close — 200%</option></select> Effects and the figure scale together.</p><p>Revelation uses the approved 4× size. Poison is enlarged to 4× its previous size and shown alongside the approved doubled bleed. The first panel directly compares corrected poison on the left with approved bleed on the right; the other panels compare previous and approved sizes. The effect pixels come from the client.</p><div class="effects"><section class="card"><h2>Poison vs bleed — current sizes</h2><canvas id="fx119" width="400" height="210"></canvas></section><section class="card"><h2>Saradomin: Revelation — approved 4×</h2><canvas id="fx117" width="400" height="210"></canvas></section><section class="card"><h2>Bleed application / reopening</h2><canvas id="fx118" width="400" height="210"></canvas></section></div>
<script>
const gods=['basic','saradomin','zamorak','guthix'],frames={},effects={};let t=0,last=performance.now(),paused=false;
for(const god of gods){frames[god]=[];for(let i=0;i<(god==='basic'?1:6);i++){let im=new Image();im.src=god+'-'+i+'.png';frames[god].push(im)}let s=document.createElement('section');s.className='card';s.innerHTML='<h2>'+({basic:'Basic bolt',saradomin:'Saradomin',zamorak:'Zamorak',guthix:'Guthix'})[god]+'</h2><canvas id="shot-'+god+'" width="320" height="220"></canvas>';document.querySelector('main').append(s)}
for(const id of [117,118,119]){effects[id]=[];for(let i=0;i<(id===117?10:id===119?16:15);i++){let im=new Image();im.src='effect-'+id+'-'+i+'.png';effects[id].push(im)}}
function shoot(god){let c=document.getElementById('shot-'+god),x=c.getContext('2d');x.imageSmoothingEnabled=false;x.clearRect(0,0,c.width,c.height);let d=document.getElementById('direction').value;d=d==='auto'?Math.floor(t/1900)%8:Number(d);let a=d*Math.PI/4,dx=Math.cos(a),dy=Math.sin(a),p=Math.min(1,(t%1900)/1350),cx=160+(p*140-70)*dx,cy=110+(p*140-70)*dy;
x.strokeStyle='#51606c';x.setLineDash([3,7]);x.beginPath();x.moveTo(160-75*dx,110-75*dy);x.lineTo(160+75*dx,110+75*dy);x.stroke();x.setLineDash([]);if(t%1900>1500)return;
let f=god==='basic'?0:Math.floor(t/133)%6,im=frames[god][f];if(!im.complete||!im.naturalWidth)return;let z=document.getElementById('large').checked?2:1;x.save();x.translate(Math.round(cx),Math.round(cy));x.rotate(a+Math.PI);x.drawImage(im,-48*z,-48*z,96*z,96*z);x.restore()}
function effect(id){let c=document.getElementById('fx'+id),x=c.getContext('2d');x.imageSmoothingEnabled=false;x.clearRect(0,0,c.width,c.height);let phase=t%1700,f=Math.floor(phase/40);for(let i=0;i<2;i++){let selected=id===119&&i===1?118:id,count=selected===117?10:selected===119?16:15,im=effects[selected][f],cx=100+i*200;x.save();x.translate(cx,170);let zoom=Number(document.getElementById('effectZoom').value);x.scale(zoom,zoom);x.translate(-cx,-170);x.fillStyle='#627180';x.beginPath();x.arc(cx,50,12,0,Math.PI*2);x.fill();x.fillRect(cx-12,65,24,62);x.fillRect(cx-23,68,9,51);x.fillRect(cx+14,68,9,51);x.fillRect(cx-12,127,10,42);x.fillRect(cx+2,127,10,42);x.fillStyle='#eee';x.fillText(id===119?(i?'Approved bleed':'Corrected poison'):(i?(id===117?'Approved: 4×':'Approved: 2×'):'Previous'),cx-48,198);let size=id===117?[27,108][i]:id===119?[164,82][i]:41*(i+1);if(f<count&&im&&im.complete&&im.naturalWidth)x.drawImage(im,cx-size/2,95-size/2,size,size);x.restore()}}
function loop(now){if(!paused)t+=Math.min(50,now-last);last=now;for(let g of gods)shoot(g);effect(117);effect(118);effect(119);requestAnimationFrame(loop)}requestAnimationFrame(loop);document.getElementById('pause').onclick=()=>{paused=!paused;document.getElementById('pause').textContent=paused?'Resume':'Pause'};
</script>''')
print(out/'index.html')
